function writeKnownError(response: ServerResponse, error: unknown): boolean {
  if (error instanceof SyntaxError) {
    writeJson(response, {
      status: 400,
      body: { error: "invalid_json" },
    });
    return true;
  }

  if (error instanceof PromptMarketplaceError) {
    writeJson(response, {
      status: error.status,
      body: { error: { code: error.code, message: error.message } },
    });
    return true;
  }

  if (error instanceof AuthorizationError) {
    const status =
      error.code === "unauthenticated"
        ? 401
        : error.code === "project_not_found"
          ? 404
          : 403;
    const errorCode =
      status === 401
        ? "unauthenticated"
        : status === 404
          ? "resource_not_found"
          : "permission_denied";
    const message =
      status === 401
        ? "session expired"
        : status === 404
          ? "resource not found"
          : "permission denied";
    writeJson(response, envelopedError(status, errorCode, message, { reason: error.code }));
    return true;
  }

  if (error instanceof CanvasAuthorizationError) {
    const status = error.code === "canvas_not_found" ? 404 : 403;
    writeJson(response, envelopedError(
      status,
      error.code,
      status === 404 ? "canvas project not found" : "permission denied",
    ));
    return true;
  }

  if (error instanceof CanvasGenerationBatchError || error instanceof CanvasGenerationHistoryError) {
    const status = error.code.endsWith("_not_found") ? 404
      : error.code.endsWith("_forbidden") ? 403
        : error.code.includes("cycle") || error.code.includes("invalid") ? 400 : 409;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof CanvasPromptReferenceError) {
    const status = error.code.endsWith("_forbidden") ? 403
      : error.code.endsWith("_unavailable") ? 409
        : 400;
    writeJson(response, envelopedError(status, error.code, error.message, {
      ...(error.reference ? { reference: error.reference } : {}),
    }));
    return true;
  }

  if (error instanceof CanvasSettingsError) {
    const status = error.code.endsWith("_not_found") ? 404
      : error.code.endsWith("_forbidden") ? 403
        : error.code.endsWith("_conflict") ? 409
          : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof CanvasCharacterLibraryError) {
    const status = error.code.endsWith("_not_found") ? 404
      : error.code.endsWith("_forbidden") ? 403
        : error.code.endsWith("_conflict") || error.code.endsWith("_mismatch") ? 409
          : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof CanvasUploadFingerprintError) {
    const status = error.code.endsWith("_unavailable") ? 409 : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof CanvasMediaDerivationError) {
    const status = error.code.endsWith("_not_found") ? 404
      : error.code.endsWith("_forbidden") ? 403
        : error.code.includes("stale") || error.code.includes("mismatch") ? 409 : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof CanvasSessionError) {
    const status = error.code.endsWith("forbidden") ? 403 : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof CanvasAgentStateConflictError) {
    writeJson(response, envelopedError(409, error.code, "Canvas Agent 状态已变化，请刷新后重试。"));
    return true;
  }

  if (error instanceof CanvasAgentStepSkipError) {
    const status = error.code === "canvas_agent_step_not_found" ? 404 : 409;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof TextModelGatewayError) {
    const status = error.code === "provider_auth_missing" || error.code === "model_not_configured" ? 503 : 400;
    writeJson(response, envelopedError(status, error.code, "Canvas Agent 模型当前不可用。"));
    return true;
  }

  if (error instanceof AgentAssetError) {
    const status = error.code === "agent_asset_not_found" ? 404
      : error.code === "agent_asset_name_conflict" ? 409
        : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof ToolPresetError) {
    const status = error.code === "tool_preset_not_found" || error.code === "tool_preset_version_not_found"
      ? 404
      : error.code === "tool_preset_name_conflict" || error.code === "tool_preset_version_conflict"
        ? 409
        : 400;
    writeJson(response, envelopedError(status, error.code, error.message, {
      ...(error.reason ? { reason: error.reason } : {}),
      ...(error.currentVersionNumber === undefined ? {} : { currentVersionNumber: error.currentVersionNumber }),
    }));
    return true;
  }

  if (error instanceof BrandKitError) {
    const status = error.code === "brand_kit_not_found" ||
        error.code === "brand_kit_asset_not_found" ||
        error.code === "brand_kit_storage_object_not_found" ||
        error.code === "brand_kit_project_not_found"
      ? 404
      : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  if (error instanceof StorageCredentialError) {
    writeJson(response, envelopedError(503, error.code, "云存储凭证不可用，请稍后重试或联系管理员。", {
      providerCode: error.providerCode,
      providerRequestId: error.providerRequestId,
    }));
    return true;
  }

  if (error instanceof GenerationRequestValidationError) {
    writeJson(response, envelopedError(400, error.code, error.message));
    return true;
  }

  if (error instanceof ImageGenerationTargetError) {
    writeJson(response, envelopedError(400, error.code, error.message));
    return true;
  }

  if (error instanceof ImageGenerationTargetRouteError) {
    writeJson(response, error.response);
    return true;
  }

  if (error instanceof GenerationMembershipRequiredError) {
    writeJson(response, envelopedError(403, error.code, error.message));
    return true;
  }

  if (error instanceof InsufficientCreditsError) {
    writeJson(response, envelopedError(402, "insufficient_credits", "积分余额不足，请充值后再生成。"));
    return true;
  }

  if (error instanceof GenerationModelRequestValidationError) {
    writeJson(response, envelopedError(400, error.code, error.message));
    return true;
  }

  if (error instanceof GenerationModelExecutionResolutionError) {
    writeJson(response, envelopedError(400, error.code, error.message));
    return true;
  }

  if (error instanceof MembershipCreditGateError) {
    writeJson(response, envelopedError(error.status, error.code, error.message));
    return true;
  }

  if (error instanceof OfficialAssetAdminValidationError) {
    const status = error.code === "official_asset_not_found" ? 404 : 400;
    writeJson(response, envelopedError(status, error.code, error.message));
    return true;
  }

  return false;
}

function canvasAgentActorFromCanvasScope(scope: CanvasActorScope): CanvasAgentActor {
  return {
    ownerUserId: scope.ownerUserId,
    actorTeamMemberId: scope.actorTeamMemberId,
    capabilities: new Set(scope.capabilities),
  };
}

function normalizeCanvasAgentMode(value: unknown): CanvasAgentMode {
  const mode = String(value ?? "b").trim().toLowerCase();
  return mode === "c" || mode === "plan" || mode === "expert" ? mode : "b";
}

function normalizeCanvasAgentMessage(value: unknown, fallback: unknown): Record<string, unknown> {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  return { text: String(value ?? fallback ?? "") };
}

function canvasActorScopeFromAgentActor(canvasId: string, actor: CanvasAgentActor): CanvasActorScope {
  return {
    canvasId,
    ownerUserId: actor.ownerUserId,
    principal: actor.actorTeamMemberId ? "team_member" : "owner",
    actorTeamMemberId: actor.actorTeamMemberId ?? null,
    principalKey: actor.actorTeamMemberId ? `member:${actor.actorTeamMemberId}` : `owner:${actor.ownerUserId}`,
    capabilities: actor.actorTeamMemberId
      ? [capabilities.canvasView, capabilities.canvasEdit, capabilities.canvasRun]
      : [capabilities.canvasView, capabilities.canvasEdit, capabilities.canvasRun, capabilities.canvasManage],
  };
}

async function resolveCanvasAgentTaskActor(
  db: SqlDatabase,
  sessionToken: string,
  canvasProjectId: string,
  taskId: string,
  action: "view" | "run",
) {
  const scope = await authorizeCanvasActor(db, {
    sessionToken,
    canvasId: canvasProjectId,
    action,
    now: new Date(),
  });
  const actor = canvasAgentActorFromCanvasScope(scope);
  const task = await findCanvasAgentTaskForActor(db, {
    taskId,
    canvasId: canvasProjectId,
    actor,
  });
  if (!task) {
    throw new CanvasAuthorizationError("canvas_not_found");
  }
  return { scope, actor, task };
}

function writeJson(response: ServerResponse, payload: AuthHttpResponse<unknown>) {
  response.statusCode = payload.status;
  response.setHeader("content-type", "application/json; charset=utf-8");

  if (payload.cookies?.length) {
    response.setHeader("set-cookie", payload.cookies);
  }

  response.end(JSON.stringify(payload.body));
}

function writeText(
  response: ServerResponse,
  input: {
    status: number;
    contentType: string;
    body: string;
    fileName?: string | null;
  },
) {
  response.statusCode = input.status;
  response.setHeader("content-type", input.contentType);
  if (input.fileName) {
    response.setHeader("content-disposition", `attachment; filename="${input.fileName}"`);
  }
  response.end(input.body);
}

function requestId() {
  return randomUUID();
}

function enveloped(status: number, data: unknown): AuthHttpResponse<unknown> {
  return {
    status,
    body: {
      requestId: requestId(),
      data,
    },
  };
}

function envelopedError(
  status: number,
  errorCode: string,
  message: string,
  details: Record<string, unknown> = {},
): AuthHttpResponse<unknown> {
  return {
    status,
    body: {
      requestId: requestId(),
      errorCode,
      message: localizeEnvelopeErrorMessage(message),
      details,
    },
  };
}

function localizeEnvelopeErrorMessage(message: string): string {
  const value = String(message ?? "").trim();
  if (!/[A-Za-z]/.test(value)) {
    return value || "操作失败，请稍后重试。";
  }
  if (/resource not found|not found/i.test(value)) return "资源不存在或已被删除。";
  if (/permission denied|forbidden|cannot .* projects/i.test(value)) return "当前账号没有操作权限。";
  if (/unauthenticated|session expired|log in/i.test(value)) return "登录已过期，请重新登录。";
  if (/method not allowed/i.test(value)) return "请求方法不支持。";
  if (/idempotency key required/i.test(value)) return "缺少幂等请求标识。";
  if (/request conflict|revision conflict/i.test(value)) return "请求发生冲突，请刷新后重试。";
  if (/still processing/i.test(value)) return "请求仍在处理中，请稍后刷新。";
  if (/required/i.test(value)) return "缺少必要参数，请检查后重试。";
  if (/invalid/i.test(value)) return "请求参数不合法，请检查后重试。";
  if (/upload/i.test(value)) return "上传处理失败，请检查文件后重试。";
  if (/delete/i.test(value)) return "删除失败，请稍后重试。";
  if (/database_url/i.test(value)) return "数据库连接配置缺失，请联系管理员处理。";
  if (/cloud storage/i.test(value)) return "云存储未配置，请联系管理员处理。";
  if (/default .* prompt|prompt template/i.test(value)) return "默认提示词模板缺失，请联系管理员配置。";
  if (/canvas/i.test(value)) return "画布操作失败，请刷新后重试。";
  if (/storyboard|script/i.test(value)) return "剧本或分镜处理失败，请检查内容后重试。";
  return translateProviderErrorMessage(value) || "操作失败，请稍后重试。";
}

