export function isNewCanvasEnabledForActor(
  env: NodeJS.ProcessEnv,
  actor: { ownerUserId: string; actorTeamMemberId?: string | null },
) {
  if (String(env.NEW_CANVAS_ENABLED ?? "true").trim().toLowerCase() !== "false") return true;
  const ownerIds = commaSeparatedIdSet(env.NEW_CANVAS_ROLLOUT_OWNER_USER_IDS ?? env.NEW_CANVAS_ROLLOUT_USER_IDS);
  const memberIds = commaSeparatedIdSet(env.NEW_CANVAS_ROLLOUT_TEAM_MEMBER_IDS);
  return ownerIds.has(String(actor.ownerUserId ?? "").trim())
    || Boolean(actor.actorTeamMemberId && memberIds.has(String(actor.actorTeamMemberId).trim()));
}

function commaSeparatedIdSet(value: unknown) {
  return new Set(String(value ?? "").split(/[\s,]+/).map((item) => item.trim()).filter(Boolean));
}

async function uploadTrackedCloudObject(
  db: SqlDatabase,
  input: {
    runtime: UploadSessionRuntime;
    objectKey: string;
    bytes: Uint8Array;
    contentType: string;
    fileName: string;
    projectId?: string | null;
    canvasProjectId?: string | null;
    actorUserId?: string | null;
    actorDisplayName?: string | null;
    pageKey: string;
    pageUrl: string;
    sourceAction: string;
    metadata?: Record<string, unknown>;
    signedUrlExpiresInSeconds: number;
    now: Date;
  },
) {
  if (typeof input.runtime.adapter.putObject !== "function") {
    throw new Error("cloud_storage_required");
  }

  const storageObjectId = randomUUID();
  await db.query(
    `
      INSERT INTO storage_objects (
        id, project_id, canvas_project_id, bucket, object_key, content_type, size_bytes,
        metadata_json, created_by_user_id, provider, status, created_at
      )
      VALUES ($1, $2, $3, $4, $5, $6, $7, $8::jsonb, $9, $10, 'pending_upload', $11)
    `,
    [
      storageObjectId,
      input.projectId ?? null,
      input.canvasProjectId ?? null,
      input.runtime.bucket,
      input.objectKey,
      input.contentType,
      input.bytes.byteLength,
      JSON.stringify(input.metadata ?? {}),
      input.actorUserId ?? null,
      input.runtime.provider,
      input.now,
    ],
  );
  const uploadRecord = await createProjectUploadRecord(db, {
    projectId: input.projectId ?? null,
    canvasProjectId: input.canvasProjectId ?? undefined,
    storageObjectId,
    uploadSessionId: null,
    actorUserId: input.actorUserId ?? null,
    actorDisplayName: input.actorDisplayName ?? null,
    actorPhoneE164: null,
    projectName: null,
    pageKey: input.pageKey,
    pageUrl: input.pageUrl,
    sourceAction: input.sourceAction,
    fileName: input.fileName,
    objectKey: input.objectKey,
    bucket: input.runtime.bucket,
    provider: input.runtime.provider,
    contentType: input.contentType,
    sizeBytes: input.bytes.byteLength,
    publicUrl: null,
    status: "created",
    errorMessage: null,
    now: input.now,
  });

  try {
    const putResult = await input.runtime.adapter.putObject({
      bucket: input.runtime.bucket,
      objectKey: input.objectKey,
      body: input.bytes,
      contentType: input.contentType,
      contentLength: input.bytes.byteLength,
    });
    const publicUrl = buildStorageObjectPublicUrl(input.runtime, {
      bucket: input.runtime.bucket,
      objectKey: input.objectKey,
    });
    const sourceUrl = publicUrl || (await input.runtime.adapter.createSignedReadUrl({
      bucket: input.runtime.bucket,
      objectKey: input.objectKey,
      expiresAt: new Date(input.now.getTime() + input.signedUrlExpiresInSeconds * 1000),
    })).url;
    await db.query(
      `
        UPDATE storage_objects
        SET status = 'available', etag = $2, version_id = $3, last_verified_at = $4
        WHERE id = $1
      `,
      [storageObjectId, putResult?.eTag ?? null, putResult?.versionId ?? null, input.now],
    );
    await db.query(
      `
        UPDATE project_upload_records
        SET public_url = $2, status = 'uploaded', error_message = NULL, completed_at = $3
        WHERE id = $1
      `,
      [uploadRecord.id, sourceUrl, input.now],
    );
    return {
      storageObjectId,
      objectKey: input.objectKey,
      bucket: input.runtime.bucket,
      provider: input.runtime.provider,
      sourceUrl,
      publicUrl,
      eTag: putResult?.eTag ?? null,
      versionId: putResult?.versionId ?? null,
    };
  } catch (error) {
    const errorMessage = (error instanceof Error ? error.message : String(error)).slice(0, 1000);
    await db.query(
      "UPDATE storage_objects SET status = 'failed' WHERE id = $1",
      [storageObjectId],
    );
    await db.query(
      `
        UPDATE project_upload_records
        SET status = 'failed', error_message = $2, completed_at = $3
        WHERE id = $1
      `,
      [uploadRecord.id, errorMessage, input.now],
    );
    throw error;
  }
}

