function parseTeamAssetCategory(value: unknown) {
  const category = String(value ?? "").trim();
  return ["character", "scene", "prop", "voice"].includes(category)
    ? category
    : null;
}

async function hasTeamAssetNameConflict(
  db: SqlDatabase,
  input: {
    adminUserId: string;
    category: string;
    name: string;
    excludeAssetId?: string | null;
  },
) {
  const existing = await queryOne<{ id: string }>(db, `
    SELECT id
    FROM team_assets
    WHERE admin_user_id = $1
      AND asset_category = $2
      AND LOWER(BTRIM(asset_name)) = LOWER(BTRIM($3))
      AND asset_status IN ('active', 'generating', 'failed')
      AND ($4::text IS NULL OR id::text <> $4)
    LIMIT 1
  `, [input.adminUserId, input.category, input.name, input.excludeAssetId ?? null]);
  return Boolean(existing);
}

function teamAssetResourceKind(contentType: string) {
  return contentType.toLowerCase().startsWith("audio/") ? "audio" : "image";
}

function teamAssetGeneratedFileName(assetName: string, artifact: MediaGenerationArtifact) {
  const extension = String(artifact.fileExtension ?? "").trim().replace(/^\./, "")
    || String(artifact.mimeType ?? "").split("/").at(-1)?.replace("jpeg", "jpg")
    || "png";
  return `${assetName}.${extension}`;
}

async function readTeamAssetArtifactBytes(
  artifact: MediaGenerationArtifact,
  fetchImpl: typeof fetch,
) {
  if (artifact.b64Json) {
    return new Uint8Array(Buffer.from(artifact.b64Json, "base64"));
  }
  if (!artifact.url) {
    throw new Error("team_asset_generation_artifact_missing");
  }
  const artifactResponse = await fetchImpl(artifact.url);
  if (!artifactResponse.ok) {
    throw new Error("team_asset_generation_artifact_download_failed");
  }
  return new Uint8Array(await artifactResponse.arrayBuffer());
}

function teamAssetRow(row: Record<string, unknown>) {
  const storedAssetStatus = readString(row.asset_status);
  const assetUrl = readString(row.asset_url);
  const generationTaskId = readString(row.generation_task_id) || readString(row.provider_request_id) || null;
  const providerStatus = readString(row.generation_task_status) || readString(row.provider_request_status);
  const assetStatus = storedAssetStatus === "generating" && ["failed", "canceled", "manual_review_required", "result_unknown"].includes(providerStatus)
    ? "failed"
    : storedAssetStatus === "generating" && ["completed", "succeeded", "success"].includes(providerStatus) && assetUrl
      ? "active"
      : storedAssetStatus;
  const generationStatus = generationTaskId
    ? assetStatus === "active"
      ? "completed"
      : assetStatus === "failed"
        ? "failed"
        : providerStatus || "queued"
    : null;
  const rawGenerationPayload = row.generation_task_payload ?? row.provider_payload;
  const generationPayload = rawGenerationPayload && typeof rawGenerationPayload === "object" && !Array.isArray(rawGenerationPayload)
    ? rawGenerationPayload as Record<string, unknown>
    : {};
  const generationImage = generationTaskId && generationStatus === "completed" && assetUrl
    ? {
        id: generationTaskId,
        mediaKind: "image",
        url: assetUrl,
        src: assetUrl,
        previewUrl: assetUrl,
        sourceUrl: assetUrl,
        downloadUrl: assetUrl,
      }
    : null;
  return {
    id: readString(row.id),
    scope: "team",
    adminUserId: readString(row.admin_user_id),
    name: readString(row.asset_name),
    prompt: readString(row.asset_prompt) || null,
    tags: normalizeTeamAssetTags(row.tags_json),
    folderName: readString(row.folder_name),
    category: readString(row.asset_category),
    status: assetStatus,
    previewUrl: assetUrl,
    sourceUrl: assetUrl,
    resourceType: readString(row.resource_type),
    resourceSize: Number(row.resource_size ?? 0),
    storageObjectId: readString(row.storage_object_id) || null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    createdByName: readString(row.created_by_name),
    updatedByName: readString(row.updated_by_name),
    isAdminCreated: row.is_admin_created === true,
    createdUserId: readString(row.created_user_id),
    generationStatus,
    generationTaskId,
    generationResult: generationTaskId
      ? {
          status: generationStatus,
          taskId: generationTaskId,
          failureCode: readString(row.generation_task_failure_code) || readString(row.provider_failure_code) || null,
          prompt: readString(generationPayload.prompt) || readString(row.asset_prompt),
          model: readString(generationPayload.model) || null,
          parameters: generationPayload.parameters && typeof generationPayload.parameters === "object"
            ? generationPayload.parameters
            : {},
          resultAssets: generationImage ? [generationImage] : [],
          result: generationImage
            ? {
                mediaKind: "image",
                imageUrl: assetUrl,
                previewUrl: assetUrl,
                sourceUrl: assetUrl,
                downloadUrl: assetUrl,
              }
            : null,
          fixedImages: generationImage ? [generationImage] : [],
        }
      : null,
  };
}

function normalizeTeamAssetTags(value: unknown): string[] {
  let values = value;
  if (typeof values === "string") {
    try {
      values = JSON.parse(values);
    } catch {
      return [];
    }
  }
  if (!Array.isArray(values)) return [];
  return [...new Set(values.map((item) => String(item ?? "").trim()).filter(Boolean))];
}

function sanitizeOfficialAssetUploadFileName(fileName: string) {
  const basename = fileName.trim().split(/[\\/]/).filter(Boolean).at(-1) ?? "";
  const safeName = basename.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");

  if (!safeName || /^https?:/i.test(fileName)) {
    throw new Error("invalid_official_asset_upload_file_name");
  }

  return safeName;
}

function sanitizeOfficialAssetStorageFolder(folderName: string) {
  const safeName = folderName.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
  return safeName || "officialAssets";
}

function formatOfficialAssetStorageDateFolder(now: Date, timeZone: string) {
  try {
    const formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    const parts = formatter.formatToParts(now);
    const year = parts.find((part) => part.type === "year")?.value ?? "1970";
    const month = parts.find((part) => part.type === "month")?.value ?? "01";
    const day = parts.find((part) => part.type === "day")?.value ?? "01";
    return `${year}${month}${day}`;
  } catch {
    const year = now.getUTCFullYear();
    const month = `${now.getUTCMonth() + 1}`.padStart(2, "0");
    const day = `${now.getUTCDate()}`.padStart(2, "0");
    return `${year}${month}${day}`;
  }
}

function normalizeGenerationKind(kind: "image" | "video" | "audio") {
  if (kind === "audio") {
    return {
      operationName: operationNames.canvasAudioGenerate,
      workflowType: operationNames.canvasAudioGenerate,
      taskType: "episode_generate_audio",
      queueName: "generation-submit-image",
      mediaKind: "audio",
      contentType: "audio/mpeg",
      fileExtension: "mp3",
      sourcePath: null,
      configuredStorageObjectId: null,
      objectNamePrefix: "audio",
      cost: Number(process.env.CANVAS_AUDIO_GENERATION_COST ?? 30),
    };
  }
  return kind === "video"
    ? {
        operationName: operationNames.episodeVideoGenerate,
        workflowType: operationNames.episodeVideoGenerate,
        taskType: "episode_generate_video",
        queueName: "episode-generation",
        mediaKind: "video",
        contentType: "video/mp4",
        fileExtension: "mp4",
        sourcePath: process.env.MOCK_VIDEO_SOURCE_PATH?.trim() || null,
        configuredStorageObjectId: process.env.MOCK_VIDEO_STORAGE_OBJECT_ID?.trim() || null,
        objectNamePrefix: "mock-video",
        cost: Number(process.env.EPISODE_VIDEO_GENERATION_COST ?? 120),
      }
    : {
        operationName: operationNames.episodeImageGenerate,
        workflowType: operationNames.episodeImageGenerate,
        taskType: "episode_generate_image",
        queueName: "episode-generation",
        mediaKind: "image",
        contentType: "image/avif",
        fileExtension: "avif",
        sourcePath: process.env.MOCK_IMAGE_SOURCE_PATH?.trim() || null,
        configuredStorageObjectId: process.env.MOCK_IMAGE_STORAGE_OBJECT_ID?.trim() || null,
        objectNamePrefix: "mock-image",
        cost: Number(process.env.EPISODE_IMAGE_GENERATION_COST ?? 90),
      };
}

function generationCostFromModelConfig(
  fallbackCost: number,
  modelConfig?: AiModelConfigRecord,
  parameters: Record<string, unknown> = {},
) {
  const baseCredits = Number(modelConfig?.pricing.baseCredits);
  if (!Number.isFinite(baseCredits) || baseCredits < 0) {
    return fallbackCost;
  }
  const billingMode = readString(modelConfig?.pricing.billingMode);
  const durationSec = readPositiveNumber(parameters.durationSec) ??
    readPositiveNumber(modelConfig?.defaultParams.durationSec) ??
    1;
  const unitCredits = resolutionCreditsFromModelConfig(modelConfig, parameters, baseCredits);
  const cost = billingMode === "duration" && modelConfig?.mediaType === "video"
    ? unitCredits * durationSec
    : unitCredits;
  return Number.isFinite(cost) && cost >= 0
    ? (cost > 0 && cost < 1 ? 1 : Math.round(cost))
    : fallbackCost;
}

async function estimateCanvasGenerationBatchItemCredits(
  db: Awaited<ReturnType<typeof createDevDb>>,
  nodes: Array<{ nodeKey: string; mediaKind: "image" | "video" | "audio"; payload?: Record<string, unknown> }>,
  env: NodeJS.ProcessEnv,
) {
  const queueConfig = loadGenerationQueueConfig(env);
  const itemCredits: Record<string, number> = {};
  for (const node of nodes) {
    const config = normalizeGenerationKind(node.mediaKind);
    const payload = readJsonRecord(node.payload);
    const modelCode = requestModelCode(payload.model ?? payload.modelCode);
    const modelConfig = modelCode ? await findActiveAiModelConfigByCode(db, modelCode) : undefined;
    const dispatchPolicy = modelCode ? await findActiveAiModelDispatchPolicyByModelCode(db, modelCode) : undefined;
    const rawParameters = readJsonRecord(payload.parameters);
    const execution = resolveGenerationModelExecution({
      kind: node.mediaKind,
      modelCode,
      modelConfig,
      dispatchPolicy,
      parameters: rawParameters,
      fallbackQueueName: node.mediaKind === "video"
        ? queueConfig.queues.submitVideo
        : queueConfig.queues.submitImage,
    });
    itemCredits[node.nodeKey] = generationCostFromModelConfig(config.cost, modelConfig, {
      ...execution.parameters,
      ...rawParameters,
    });
  }
  return itemCredits;
}

function resolutionCreditsFromModelConfig(
  modelConfig: AiModelConfigRecord | undefined,
  parameters: Record<string, unknown>,
  fallbackCredits: number,
) {
  const resolution = readString(parameters.resolution) ||
    readString(parameters.quality) ||
    readString(parameters.ratio) ||
    readString(parameters.aspectRatio) ||
    readString(modelConfig?.defaultParams.resolution) ||
    readString(modelConfig?.defaultParams.quality) ||
    readString(modelConfig?.defaultParams.ratio) ||
    readString(modelConfig?.defaultParams.aspectRatio);
  const table = modelConfig?.pricing.resolutionCredits;
  if (!resolution || !table || typeof table !== "object" || Array.isArray(table)) {
    return fallbackCredits;
  }
  const configuredCredits = Number((table as Record<string, unknown>)[resolution]);
  return Number.isFinite(configuredCredits) && configuredCredits >= 0
    ? configuredCredits
    : fallbackCredits;
}

function readPositiveNumber(value: unknown): number | null {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

function modelConfigSupportsScriptGeneration(modelConfig: AiModelConfigRecord) {
  const tokens = [
    modelConfig.mediaType,
    modelConfig.modelCode,
    ...modelConfig.taskModes,
    ...readStringArray(modelConfig.uiConfig.supportedModes),
  ]
    .map((item) => String(item ?? "").trim().toLowerCase())
    .filter(Boolean);
  return tokens.some((token) => token === "text" || token === "text.script" || token === "script" || token.includes("script"));
}

async function findActiveScriptGenerationModelConfig(
  db: Parameters<typeof listActiveAiModelConfigs>[0],
  preferredModelCode?: string,
) {
  const normalizedPreferredModelCode = String(preferredModelCode ?? "").trim();
  if (normalizedPreferredModelCode) {
    const preferredModel = await findActiveAiModelConfigByCode(db, normalizedPreferredModelCode);
    if (preferredModel && modelConfigSupportsScriptGeneration(preferredModel)) {
      return preferredModel;
    }
  }
  const activeTextModels = await listActiveAiModelConfigs(db, { mediaType: "text" });
  const scriptModels = activeTextModels.filter(modelConfigSupportsScriptGeneration);
  return scriptModels.find((modelConfig) => generationCostFromModelConfig(0, modelConfig) > 0) ?? scriptModels[0];
}

async function reserveAndConsumeAiStoryboardPreviewCredits(
  db: Awaited<ReturnType<typeof createDevDb>>,
  input: {
    projectId: string;
    createdByUserId: string;
    teamMemberId?: string | null;
    idempotencyKey: string;
    promptPreview: string;
    modelConfig?: AiModelConfigRecord;
    modelCreditCost?: number;
    billingMetadata?: Record<string, unknown>;
    skillCreditCost?: number;
    skillAuthorGrant?: {
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    } | null;
    skillAuthorGrants?: Array<{
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    }>;
    now: Date;
  },
) {
  const configuredModelCreditCost = Number(input.modelCreditCost);
  const modelCreditCost = Number.isFinite(configuredModelCreditCost) && configuredModelCreditCost >= 0
    ? configuredModelCreditCost
    : generationCostFromModelConfig(0, input.modelConfig);
  const amount = modelCreditCost
    + Math.max(0, Math.round(Number(input.skillCreditCost) || 0));
  if (!Number.isFinite(amount) || amount <= 0) {
    return null;
  }
  const modelCode = String(input.modelConfig?.modelCode ?? "text.script").trim() || "text.script";
  const modelLabel = String(input.modelConfig?.displayName ?? "剧本模型").trim() || "剧本模型";
  const metadata = {
    targetUserId: input.createdByUserId,
    memberId: input.teamMemberId ?? undefined,
    projectId: input.projectId,
    modelCode,
    modelLabel,
    mediaType: "text",
    kind: "text",
    taskType: "ai_storyboard_preview",
    operation: "ai_storyboard_preview",
    billingEvent: "consumed",
    outcome: "consumed",
    promptPreview: input.promptPreview,
    ...(input.billingMetadata ?? {}),
  };
  if (!await hasActiveGenerationMembership(db, { userId: input.createdByUserId, now: input.now })) {
    throw new GenerationMembershipRequiredError();
  }
  return reserveConsumeAndGrantUserScriptAnalysisCredits(db, {
    userId: input.createdByUserId,
    amount,
    projectId: input.projectId,
    idempotencyKey: input.idempotencyKey,
    sourceType: "episode_generation_task",
    reason: "script generation",
    allocationKey: "ai_storyboard_preview",
    metadata,
    skillAuthorGrant: input.skillAuthorGrant,
    skillAuthorGrants: input.skillAuthorGrants,
    now: input.now,
  });
}

async function reserveAndConsumeSimpleTeamMemberCredits(
  db: Awaited<ReturnType<typeof createDevDb>>,
  input: {
    projectId: string | null;
    teamMemberId: string;
    idempotencyKey: string;
    promptPreview: string;
    modelConfig?: AiModelConfigRecord;
    creditCostOverride?: number;
    billingMetadata?: Record<string, unknown>;
    skillAuthorGrant?: {
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    } | null;
    skillAuthorGrants?: Array<{
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    }>;
    now: Date;
  },
) {
  const amount = Number.isFinite(input.creditCostOverride) && Number(input.creditCostOverride) >= 0
    ? Math.round(Number(input.creditCostOverride))
    : generationCostFromModelConfig(0, input.modelConfig);
  if (!Number.isFinite(amount) || amount <= 0) {
    return null;
  }
  const sourceId = uuidFromIdempotencyKey(input.idempotencyKey);
  const modelCode = String(input.modelConfig?.modelCode ?? "text.script").trim() || "text.script";
  const modelLabel = String(input.modelConfig?.displayName ?? "剧本模型").trim() || "剧本模型";
  const metadata = {
    targetUserId: input.teamMemberId,
    memberId: input.teamMemberId,
    projectId: input.projectId,
    modelCode,
    modelLabel,
    mediaType: "text",
    kind: "text",
    taskType: "ai_storyboard_preview",
    operation: "ai_storyboard_preview",
    billingEvent: "consumed",
    outcome: "consumed",
    promptPreview: input.promptPreview,
    ...(input.billingMetadata ?? {}),
  };
  await db.query("BEGIN");
  try {
    const member = await queryOne<{ user_id: string; member_credits: number | string }>(
      db,
      `SELECT user_id, member_credits
       FROM team_members
       WHERE id = $1
         AND status = 'active'
         AND deleted_at IS NULL
       LIMIT 1
       FOR UPDATE`,
      [input.teamMemberId],
    );
    if (!member) {
      throw new InsufficientCreditsError();
    }
    const existingCharge = await queryOne<{
      id: string;
      amount: number | string;
      metadata_json: Record<string, unknown>;
    }>(
      db,
      `SELECT id, amount, metadata_json
       FROM credit_ledger_entries
       WHERE user_id = $1
         AND team_member_id = $2
         AND entry_type = 'transfer_out'
         AND source_type = 'team_member_generation_task'
         AND source_id = $3
       LIMIT 1`,
      [member.user_id, input.teamMemberId, sourceId],
    );
    if (existingCharge && (
      Number(existingCharge.amount) !== amount
      || existingCharge.metadata_json.skillId !== metadata.skillId
      || existingCharge.metadata_json.modelCode !== metadata.modelCode
    )) {
      throw new IdempotencyConflictError();
    }
    if (!existingCharge) {
      if (Number(member.member_credits ?? 0) < amount) {
        throw new InsufficientCreditsError();
      }
      const updated = await queryOne<{ member_credits: number | string }>(
        db,
        `UPDATE team_members
         SET member_credits = member_credits - $2,
             updated_at = $3
         WHERE id = $1
           AND status = 'active'
           AND deleted_at IS NULL
           AND member_credits >= $2
         RETURNING member_credits`,
        [input.teamMemberId, amount, input.now],
      );
      if (!updated) {
        throw new InsufficientCreditsError();
      }

      await queryOne<{ id: string }>(
        db,
        `INSERT INTO credit_ledger_entries (
           id, user_id, team_member_id, reservation_id, allocation_id, entry_type,
           amount, available_delta, reserved_delta, consumed_delta, balance_after,
           source_type, source_id, reason, metadata_json, created_by_user_id, created_at
         ) VALUES (
           $1, $2, $3, NULL, NULL, 'transfer_out', $4, -($4::int), 0, 0, $9,
           'team_member_generation_task', $5, $6, $7::jsonb, $2, $8
         )
         RETURNING id`,
        [
          randomUUID(),
          member.user_id,
          input.teamMemberId,
          amount,
          sourceId,
          "成员生成消耗积分",
          JSON.stringify(metadata),
          input.now,
          Number(updated.member_credits),
        ],
      );
    }

    await db.query("COMMIT");
    return {
      reservation: {
        id: sourceId,
        userId: member.user_id,
        teamMemberId: input.teamMemberId,
        projectId: input.projectId,
        workflowId: null,
        taskId: null,
        amountTotal: amount,
        amountReserved: 0,
        amountConsumed: amount,
        amountReleased: 0,
        status: "settled" as const,
        sourceType: "team_member_generation_task",
        sourceId,
        reason: "成员生成消耗积分",
        metadata,
        createdByUserId: member.user_id,
        createdAt: input.now,
        updatedAt: input.now,
      },
    };
  } catch (error) {
    await db.query("ROLLBACK").catch(() => undefined);
    throw error;
  }
}

async function reserveConsumeAndGrantUserScriptAnalysisCredits(
  db: Awaited<ReturnType<typeof createDevDb>>,
  input: {
    userId: string;
    amount: number;
    projectId?: string | null;
    idempotencyKey: string;
    sourceType?: string;
    allocationKey?: string;
    reason?: string;
    metadata: Record<string, unknown>;
    skillAuthorGrant?: {
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    } | null;
    skillAuthorGrants?: Array<{
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    }>;
    now: Date;
  },
) {
  if (!Number.isFinite(input.amount) || input.amount <= 0) {
    return null;
  }
  await db.query("BEGIN");
  try {
    const walletUserIds = [input.userId]
      .filter((userId): userId is string => Boolean(userId))
      .sort();
    await db.query(
      "SELECT id FROM users WHERE id = ANY($1::uuid[]) ORDER BY id FOR UPDATE",
      [walletUserIds],
    );
    const reservation = await reserveCreditsInTransaction(db, {
      userId: input.userId,
      projectId: input.projectId ?? null,
      amount: Math.round(input.amount),
      sourceType: input.sourceType ?? "user_script_analysis",
      sourceId: uuidFromIdempotencyKey(input.idempotencyKey),
      reason: input.reason ?? "小说转剧本分析",
      metadata: input.metadata,
      createdByUserId: input.userId,
      now: input.now,
    });
    if (
      reservation.reservation.metadata.skillId !== input.metadata.skillId
      || reservation.reservation.metadata.modelCode !== input.metadata.modelCode
    ) {
      throw new IdempotencyConflictError();
    }
    await settleReservationAllocationInTransaction(db, {
      reservationId: reservation.reservation.id,
      allocationKey: input.allocationKey ?? "user-script-analysis",
      amount: Math.round(input.amount),
      outcome: "consumed",
      metadata: input.metadata,
      now: input.now,
    });
    await db.query("COMMIT");
    return reservation;
  } catch (error) {
    await db.query("ROLLBACK").catch(() => undefined);
    throw error;
  }
}

async function grantPromptSkillAuthorCredits(
  db: Awaited<ReturnType<typeof createDevDb>>,
  input: {
    payerUserId: string;
    skillAuthorGrant?: {
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    } | null;
    skillAuthorGrants?: Array<{
      userId: string;
      amount: number;
      sourceId: string;
      metadata: Record<string, unknown>;
    }>;
    now: Date;
  },
) {
  const grants = [input.skillAuthorGrant, ...(input.skillAuthorGrants ?? [])]
    .filter((grant): grant is NonNullable<typeof grant> => Boolean(grant && grant.amount > 0));
  for (const grant of grants) {
    await grantCredits(db, {
      userId: grant.userId,
      amount: grant.amount,
      sourceType: "prompt_skill_usage_earning",
      sourceId: grant.sourceId,
      reason: "私人提示词技能使用分成",
      metadata: grant.metadata,
      createdByUserId: input.payerUserId,
      now: input.now,
    });
  }
}

