async function getEpisodeContext(
  db: Awaited<ReturnType<typeof createDevDb>>,
  input: {
    episodeId: string;
    sessionToken: string;
    userId: string;
    capability?: (typeof capabilities)[keyof typeof capabilities];
    now: Date;
  },
) {
  const episode = await queryOne<{
    id: string;
    project_id: string;
    title: string;
    sequence: number;
    status: string;
  }>(
    db,
    "SELECT id, project_id, title, sequence, status FROM episodes WHERE id = $1",
    [input.episodeId],
  );
  if (!episode) {
    return null;
  }

  const actor = await resolveActorContext(db, {
    sessionToken: input.sessionToken,
    projectId: episode.project_id,
    capability: input.capability,
    now: input.now,
  });
  const project = await queryOne<{
    id: string;
    name: string;
    phase: string;
    aspect_ratio: string;
    resolution: string;
    project_style_code: string;
  }>(
    db,
    "SELECT id, name, phase, aspect_ratio, resolution, project_style_code FROM projects WHERE id = $1",
    [episode.project_id],
  );
  if (!project) {
    return null;
  }

  const credit = actor.teamMember
    ? await getSimpleTeamMemberCreditBalance(db, {
        userId: input.userId,
        memberId: actor.teamMember.id,
      })
    : await getUserCreditBalance(db, input.userId);
  return {
    actor,
    episode,
    project,
    ...credit,
    userId: input.userId,
  };
}

