async function resolveTaskContext(
  db: Awaited<ReturnType<typeof createDevDb>>,
  input: {
    taskId: string;
    sessionToken: string;
    now: Date;
  },
) {
  const task = await queryOne<{
    id: string;
    project_id: string | null;
    workflow_id: string;
    task_type: string;
    status: string;
    failure_code: string | null;
    input_snapshot_json: Record<string, unknown> | string;
    target_entity_type: string;
    target_entity_id: string;
    created_at: Date | string;
    updated_at: Date | string;
    created_by_user_id: string | null;
  }>(
    db,
    `
      SELECT task.id, task.project_id, task.workflow_id, task.task_type, task.status, task.failure_code,
             task.input_snapshot_json, task.target_entity_type, task.target_entity_id,
             task.created_at, task.updated_at, workflow.created_by_user_id
      FROM tasks task
      JOIN workflows workflow ON workflow.id = task.workflow_id
      WHERE task.id = $1
    `,
    [input.taskId],
  );
  if (!task) {
    return null;
  }
  const actor = await resolveActorContext(db, {
    sessionToken: input.sessionToken,
    projectId: task.project_id ?? undefined,
    now: input.now,
  });
  if (!task.project_id && task.created_by_user_id !== actor.userId) {
    return null;
  }
  return { task, actor };
}

async function ensureMockGenerationStorageObject(
  db: Awaited<ReturnType<typeof createDevDb>>,
  input: {
    kind: "image" | "video";
    projectId: string | null;
    canvasProjectId?: string | null;
    canvasActorScope?: CanvasActorScope;
    episodeId: string | null;
    taskId: string;
    userId: string;
    now: Date;
    runtime: UploadSessionRuntime;
  },
) {
  const config = normalizeGenerationKind(input.kind);
  if (config.configuredStorageObjectId) {
    const existing = await queryOne<{
      id: string;
      bucket: string;
      object_key: string;
      content_type: string;
    }>(
      db,
      "SELECT id, bucket, object_key, content_type FROM storage_objects WHERE id = $1",
      [config.configuredStorageObjectId],
    );
    if (existing) {
      return existing;
    }
  }

  const media = await readMockGenerationMedia(config);
  const objectScope = input.episodeId ? `episodes/${input.episodeId}` : `generation/${input.taskId}`;
  const objectName = `${objectScope}/mock/${config.objectNamePrefix}-${input.taskId}.${media.fileExtension}`;
  const storageObject = await createScopedStorageObject(db, {
    userId: input.userId,
    actorScope: input.canvasActorScope,
    projectId: input.projectId,
    canvasProjectId: input.canvasProjectId,
    bucket: input.runtime.bucket,
    objectName,
    contentType: media.contentType,
    sizeBytes: media.bytes.byteLength,
    provider: input.runtime.provider,
    status: "available",
    metadata: {
      episodeId: input.episodeId,
      taskId: input.taskId,
      mockSource: config.mediaKind,
      mockFallback: media.usedFallback,
    },
    createdByUserId: input.userId,
    now: input.now,
  });

  if (
    (input.runtime.mode === "cos" || input.runtime.mode === "s3_compatible") &&
    typeof input.runtime.adapter.putObject === "function"
  ) {
    await input.runtime.adapter.putObject({
      bucket: storageObject.bucket,
      objectKey: storageObject.objectKey,
      body: media.bytes,
      contentType: media.contentType,
    });
  } else {
    await writeLocalStorageObject({
      bucket: storageObject.bucket,
      objectKey: storageObject.objectKey,
      bytes: media.bytes,
    });
  }

  return {
    id: storageObject.id,
    bucket: storageObject.bucket,
    object_key: storageObject.objectKey,
    content_type: storageObject.contentType,
  };
}

